#ifdef GL_ES
precision mediump float;
#endif


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Parameters for the side line
    float u_lineWidth = 0.02;  // Side line width
    float u_dotHeight = 0.2;   // Dot height for dotted line pattern
    vec3 u_lineColor = vec3(1.0, 1.0, 1.0);  // Line color
    bool u_dottedLine = true;  // Toggle for dotted line
    float u_curveAmount = 0.0;  // Curve amount for the line
    float u_linePos = 0.0;  // Horizontal position of the line

    vec2 uv = fragCoord / iResolution.xy;
    uv.x = (uv.x - 0.5) * (iResolution.x / iResolution.y);
    //uv.x = (uv.x - 0.5) * 2.0; // Adjusted to use full screen width

    // Apply curvature effect (shifting the x-position based on y-coordinate)
    float curve = u_curveAmount * uv.y * uv.y;
    uv.x -= curve;

    // Calculate the line's position and width
    float line = abs(uv.x - u_linePos);

    // Apply smoothstep for solid lines or dashed pattern for dotted lines
    float linePattern = u_dottedLine ? step(0.5, fract(uv.y / u_dotHeight + 0.25)) : 1.0;

    float laneLine;
        if (u_curveAmount != 0.0) {
            laneLine = 1.0 - smoothstep(u_lineWidth * 0.5, u_lineWidth, line);
        } else {
            laneLine = 1.0 - step(u_lineWidth * 0.5, line);
        }

    // Combine line pattern (dotted or solid) and apply color
    vec3 color = mix(vec3(0.1, 0.1, 0.1), u_lineColor, laneLine * linePattern);

    fragColor = vec4(color, 1.0);
}
